select.where:
     and user_id = #{userId}
     and nickname like concat('%', #{nickname}, '%')
     and order_no = #{orderNo}
     and power_bank_no = #{powerBankNo}
     and start_time = #{startTime}
     and start_station_id = #{startStationId}
     and start_station_name like concat('%', #{startStationName}, '%')
     and start_cabinet_no = #{startCabinetNo}
     and end_time = #{endTime}
     and end_station_id = #{endStationId}
     and end_station_name like concat('%', #{endStationName}, '%')
     and end_cabinet_no = #{endCabinetNo}
     and duration = #{duration}
     and fee_rule = #{feeRule}
     and fee_rule_id = #{feeRuleId}
     and total_amount = #{totalAmount}
     and deduct_amount = #{deductAmount}
     and real_amount = #{realAmount}
     and pay_time = #{payTime}
     and transaction_id = #{transactionId}
     and status = #{status}
and del_flag = 0
